def feature(s):
    s = s or {}
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    return float(log1p(v))

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    occupied = 0.0
    spheres = 0.0
    for site in sites:
        o = site.get('occupancy')
        o = max(0.0, o if o is not None else 1.0)
        occupied += o
        p = props.get(site.get('element')) or {}
        r = p.get('covalent_radius_A')
        if r is None or r <= 0:
            r = p.get('atomic_radius_A')
        if r is not None and r > 0:
            spheres += o * r ** 3
    v = (s.get('lattice') or {}).get('volume_A3')
    if v is None or v <= 0:
        a = s.get('volume_per_atom_A3')
        v = a * occupied if a is not None and a > 0 else 0.0
    return float(4.0 * pi * spheres / (3.0 * v)) if v > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [1.0] * n
    occ = [0.0] * n
    for i, site in enumerate(sites):
        o = site.get('occupancy')
        occ[i] = max(0.0, o if o is not None else 1.0)
        r = (props.get(site.get('element')) or {}).get('covalent_radius_A')
        if r is not None and r > 0:
            radii[i] = r
    best = inf
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[i] > 0 and occ[j] > 0:
            best = min(best, d / (radii[i] + radii[j]))
    return float(best) if best < inf else 0.0

