def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    near = [inf] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[i] > 0 and occ[j] > 0:
            near[i] = min(near[i], d)
    weight = sum(occ[i] for i in range(n) if near[i] < inf)
    if weight <= 0:
        return 0.0
    return float(sum(occ[i] * near[i] for i in range(n) if near[i] < inf) / (weight * v ** (1.0 / 3.0)))

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    n = len(sites)
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    near = [inf] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[i] > 0 and occ[j] > 0:
            near[i] = min(near[i], d)
    cn = [0.0] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and near[i] < inf and d <= 2.0 * near[i]:
            cn[i] += occ[j] * exp(1.0 - (d / near[i]) ** 6)
    total = sum(occ)
    if total <= 0:
        return 0.0
    mean = sum(occ[i] * cn[i] for i in range(n)) / total
    if mean <= 0:
        return 0.0
    variance = sum(occ[i] * (cn[i] - mean) ** 2 for i in range(n)) / total
    return float(sqrt(max(0.0, variance)) / mean)

