def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    n = len(sites)
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    elements = [x.get('element') for x in sites]
    total = sum(occ)
    if total <= 0:
        return 0.0
    counts = {}
    for i in range(n):
        counts[elements[i]] = counts.get(elements[i], 0.0) + occ[i]
    expected = 1.0 - sum((v / total) ** 2 for v in counts.values())
    near = [inf] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[i] > 0 and occ[j] > 0:
            near[i] = min(near[i], d)
    unlike = 0.0
    weight = 0.0
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and near[i] < inf and d <= 1.35 * near[i]:
            w = occ[i] * occ[j]
            weight += w
            if elements[i] != elements[j]:
                unlike += w
    return float(unlike / weight - expected) if weight > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    chi = [(props.get(x.get('element')) or {}).get('eneg') for x in sites]
    known = sum(occ[i] for i in range(n) if chi[i] is not None)
    total = sum(occ)
    if known <= 0 or total <= 0:
        return 0.0
    mean = sum(occ[i] * chi[i] for i in range(n) if chi[i] is not None) / known
    q = [chi[i] - mean if chi[i] is not None else 0.0 for i in range(n)]
    value = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d < 6.0:
            taper = (1.0 - d / 6.0) ** 2
            value += occ[i] * occ[j] * q[i] * q[j] * taper / d
    return float(value / (2.0 * total))

