    valence = [(props.get(x.get('element')) or {}).get('valence_electrons') for x in sites]
    total = sum(occ)
    if total <= 0:
        return 0.0
    value = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d < 6.0 and valence[i] is not None and valence[j] is not None:
            value += occ[i] * occ[j] * valence[i] * valence[j] * (1.0 - d / 6.0) ** 2 / max(d, 0.25) ** 3
    return float(value / (2.0 * total))

def feature(s):
    s = s or {}
    m = (s.get('lattice') or {}).get('matrix')
    if m is None or len(m) != 3 or any(len(row) != 3 for row in m):
        return 0.0
    matrix = np.asarray(m)
    gram = np.matmul(matrix, matrix.T)
    eigen = np.linalg.eigvalsh(gram)
    largest = float(eigen[2])
    if largest <= 0:
        return 0.0
    smallest = max(float(eigen[0]), largest * 1e-12)
    return float(0.5 * log(largest / smallest))

def feature(s):
    s = s or {}
    props = s.get('element_properties') or {}
    value = 0.0
    weight = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        if fraction is None or fraction <= 0:
            continue
        p = props.get(element) or {}
        ionization = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if ionization is not None and affinity is not None:
            value += fraction * 0.5 * (ionization - affinity)
            weight += fraction
    return float(value / weight) if weight > 0 else 0.0

